def commonToAllThree(a, b, c):
    i = j = k = 0
    res = []
    while i < len(a) and j < len(b) and k < len(c):
        x, y, z = a[i], b[j], c[k]
        if x == y == z:
            if not res or res[-1] != x:
                res.append(x)
            i += 1
            j += 1
            k += 1
        else:
            m = max(x, y, z)
            if x < m:
                i += 1
            if y < m:
                j += 1
            if z < m:
                k += 1
    return res
